"""Code-native, synthetic product illustrations; never presented as app screenshots."""

def wave():
    heights=[12,20,33,18,42,55,27,65,39,20,49,70,33,56,24,41,17,28,12]
    return '<span class="wave" aria-hidden="true">'+''.join(f'<i style="--bar:{n}%"></i>' for n in heights)+'</span>'

def illustrated_home(l,c,link):
    zh=l=='zh'
    def t(a,b):return a if zh else b
    mark='<img src="assets/brand-mark.png" width="40" height="40" alt="">'
    note=t('产品流程示意 · 全部为合成资料，非运行截图','Product illustration · Synthetic material, not running app screenshots')
    hero=f'''<section class="visual-hero"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span>{c['stage']}</p><h1>{t('把留下的信息，<br><span>整理成自己的记忆。</span>','Keep the traces.<br><span>Make them your memory.</span>')}</h1><p class="intro">{t('抬腕记录，随手导入，在电脑上重新连接。<br>每一段记忆，都有可以回去的来处。','Capture on your wrist. Bring your text.<br>Gather on Mac, with a way back to every source.')}</p><div class="actions">{link('',c['source'],'button primary')}<a class="button secondary" href="start.html">{c['build']} <span aria-hidden="true">→</span></a></div><p class="small release">{c['note']}</p></div>
    <figure class="device-stage" aria-label="{t('手表和手机记录，Mac汇集资料的合成示意','Synthetic illustration of watch and phone capture with a Mac source library')}">
      <div class="stage-caption"><span>01 / CAPTURE</span><span>02 / GATHER</span><span>03 / RETURN</span></div>
      <div class="mac-device" aria-hidden="true"><div class="window-bar"><span class="window-dots"><i></i><i></i><i></i></span><span>Tracebook</span><span>⌘</span></div><div class="mac-screen"><div class="mac-sidebar">{mark}<b>{t('我的迹库','My Tracebook')}</b><span class="selected">▧ &nbsp; {t('资料库','Library')}</span><span>◷ &nbsp; {t('每日记录','Daily records')}</span><span>◇ &nbsp; {t('长期记忆','Memory')}</span><span class="sidebar-bottom">{t('自己的文件夹','Your own folder')} ↗</span></div><div class="mac-content"><div class="mock-toolbar"><span>{t('你的资料库','Your source library')}</span><span>⌕</span></div><div class="mock-date">{t('合成资料 / 一个普通的星期天','SYNTHETIC MATERIAL / AN ORDINARY SUNDAY')}</div><h3>{t('让零散的日常，<br>在这里相遇。','Let the pieces<br>find their place.')}</h3><div class="library-row"><span class="source-icon">≋</span><div><b>{t('散步时的想法','A thought on a walk')}</b><small>09:10 · {t('原音已保存','Audio saved')}</small></div><span>↗</span></div><div class="library-row"><span class="source-icon">≡</span><div><b>{t('周末路线.md','weekend-route.md')}</b><small>14:30 · {t('文字资料','Text document')}</small></div><span>↗</span></div><div class="library-row"><span class="source-icon">⌘</span><div><b>{t('离线地图说明','Offline map notes')}</b><small>18:00 · {t('本地工具输入','Local tool input')}</small></div><span>↗</span></div></div></div></div>
      <div class="phone-device" aria-hidden="true"><div class="phone-notch"></div><div class="phone-top">9:41 <span>•••</span></div><div class="record-label"><i></i>{t('录音示意','Recording illustration')}</div><div class="record-time">00:42</div>{wave()}<div class="record-controls"><span>Ⅱ</span><span class="record-stop"><i></i></span></div><small>{t('声音先留在手机','First, keep the sound')}</small></div>
      <div class="watch-device" aria-hidden="true"><div class="watch-face"><div class="watch-top">{mark}<span>09:10</span></div><span class="watch-time">00:42</span>{wave()}<span class="watch-save">■ &nbsp; {t('保存片刻','Keep the moment')}</span></div></div>
      <div class="device-label label-watch">Apple Watch <span>{t('抬腕留下','Capture a moment')}</span></div><div class="device-label label-phone">iPhone <span>{t('随手记录','Capture anywhere')}</span></div><div class="device-label label-mac">Mac <span>{t('汇集、阅读、整理','Gather, read, organize')}</span></div>
      <figcaption>{note}</figcaption>
    </figure></section>'''
    capture=f'''<section class="visual-section"><div class="section-copy"><p class="eyebrow">01 / {t('留下与汇集','CAPTURE & GATHER')}</p><h2>{t('一天的线索，<br>不止一种来处。','A day leaves<br>more than one kind of trace.')}</h2><p>{t('语音、已有文字、本地工具输入。<br>先各自留下，再带着来源汇集。','Voice, existing text and local tool inputs.<br>Bring them together without losing their origins.')}</p><span class="capability">{t('已有：采集、导入与来源阅读','Available: capture, import and source reading')}</span></div><div class="day-scene"><div class="scene-header"><span>{t('一个普通的星期天','An ordinary Sunday')}</span><small>{t('合成资料示意','Synthetic example')}</small></div><div class="day-entry"><time>09:10</time><div><span class="type-tag">APPLE WATCH / {t('原音','AUDIO')}</span><h3>{t('散步时，留下一个想法。','A thought, saved on a walk.')}</h3><div class="audio-strip">{wave()}<span>00:42</span></div><p class="scene-note">{t('原音已保存 · 真实自动转写仍在开发','Audio saved · Real automatic transcription is still in development')}</p></div></div><div class="day-entry"><time>14:30</time><div><span class="type-tag">MARKDOWN / {t('文字资料','TEXT')}</span><h3>{t('周末路线.md','weekend-route.md')}</h3><p class="sample-quote">{t('“路线从东门出发，沿河走到旧桥。”','“Start at the east gate. Follow the river to the old bridge.”')}</p></div></div><div class="day-entry"><time>18:00</time><div><span class="type-tag">{t('本地工具 / 输入','LOCAL TOOL / INPUT')}</span><h3>{t('另一种思考，也值得保留。','Keep another kind of thinking.')}</h3><p class="sample-quote">{t('“把离线地图的使用说明也保留下来。”','“Keep the instructions for using the offline map, too.”')}</p></div></div><div class="scene-foot">{t('保留日期 · 区分来源 · 可以回看','Keep dates · Distinguish sources · Return to the original')}</div></div></section>'''
    memory=f'''<section class="visual-section reverse"><div class="section-copy"><p class="eyebrow">02 / {t('确认，而非替你认定','REVIEW, NOT ASSUME')}</p><h2>{t('不是每一句话，<br>都该成为你的记忆。','Not every sentence<br>should become your memory.')}</h2><p>{t('原文是原文，建议是建议。<br>由你确认，才值得长期留下。','The original is evidence. A suggestion is not a fact.<br>You decide what deserves to stay.')}</p><span class="capability">{t('已有手动多来源与修订 · 自动模型整理开发中','Manual multi-source revision exists · Model automation in development')}</span></div><div class="memory-scene"><div class="scene-header"><span>{t('记忆的三个层次','Three layers of memory')}</span><small>{t('概念示意','Concept illustration')}</small></div><div class="memory-layer original"><span>01</span><div><small>{t('原始资料','ORIGINAL MATERIAL')}</small><h3>{t('保留说过的原话。','Keep what was actually said.')}</h3><p>{t('来源、时间、内容版本','Source, time and content version')}</p></div><span class="layer-symbol">≡</span></div><div class="memory-connector">↓</div><div class="memory-layer suggestion"><span>02</span><div><small>{t('手动提出候选 · 待确认','MANUAL CANDIDATE · AWAITING REVIEW')}</small><h3>{t('这件事，值得长期记住吗？','Is this worth remembering?')}</h3><p>{t('建议不等于事实，未操作不代表确认','A suggestion is not fact. Silence is not consent.')}</p></div><span class="layer-symbol">◇</span></div><div class="memory-connector">↓ &nbsp; {t('由你确认','YOUR CONFIRMATION')}</div><div class="memory-layer confirmed"><span>03</span><div><small>{t('已确认记忆','CONFIRMED MEMORY')}</small><h3>{t('留下你认可的部分。','Keep the part you agree with.')}</h3><p>{t('可修订、停用、恢复；保留依据与历史','Revise, deactivate or restore; keep evidence and history')}</p></div><span class="layer-symbol">✓</span></div></div></section>'''
    source=f'''<section class="visual-section"><div class="section-copy"><p class="eyebrow">03 / {t('回到原文','BACK TO THE SOURCE')}</p><h2>{t('找到一条线索，<br>也找得到它的来处。','Find the trace.<br>Then check its source.')}</h2><p>{t('检索不是猜测。打开来源片段，<br>在原文里核对，而不是只相信一句结论。','Open a source excerpt and check it in context.<br>Do not settle for a conclusion without evidence.')}</p><span class="capability">{t('已有本地检索 · 不会生成模型回答','Local retrieval exists · It does not generate model answers')}</span></div><div class="source-scene"><div class="scene-header"><span>{t('资料检索','Source retrieval')}</span><small>{t('合成示例','Synthetic example')}</small></div><div class="search-illustration">⌕ <span>{t('河边路线','riverside route')}</span></div><div class="result-sheet"><span class="type-tag">01 / {t('文字资料 · 来源片段','TEXT DOCUMENT · SOURCE EXCERPT')}</span><h3>{t('周末路线.md','weekend-route.md')}</h3><p>{t('路线从东门出发，<mark>沿河走到旧桥</mark>。返程前先下载好离线地图。','Start at the east gate. <mark>Follow the river to the old bridge.</mark> Download the offline map before heading back.')}</p><a href="#original-example" class="source-anchor">{t('在下方核对原文','Check the original below')} <span aria-hidden="true">↓</span></a></div><div id="original-example" class="original-sheet" tabindex="-1"><div><span>{t('原文 / 合成文字','ORIGINAL / SYNTHETIC TEXT')}</span><small>14:30 · Markdown</small></div><p><span class="line-no">01</span>{t('周末路线','Weekend route')}</p><p><span class="line-no">02</span>{t('路线从东门出发，沿河走到旧桥。','Start at the east gate. Follow the river to the old bridge.')}</p><p><span class="line-no">03</span>{t('返程前先下载好离线地图。','Download the offline map before heading back.')}</p></div></div></section>'''
    files=f'''<section class="ownership"><div class="folder-art" aria-hidden="true"><div class="folder-back"></div><div class="paper paper-one"><span>≋</span><i></i><i></i></div><div class="paper paper-two"><span>≡</span><i></i><i></i></div><div class="folder-front">{mark}<span>Tracebook</span></div><span class="file-pill">.md &nbsp; .txt &nbsp; {t('来源与历史','sources & history')}</span></div><div><p class="eyebrow">04 / {t('文件归你','FILES YOU OWN')}</p><h2>{t('不是被锁住的记忆。<br>是你自己的资料。','Not a locked-away memory.<br>Your own material.')}</h2><p>{t('选择自己的资料夹，保留历史与人工修改。<br>文字可以带走，来源不必忘记。','Choose your folder. Keep history and your edits.<br>Take your text with you, without forgetting its source.')}</p><p class="small">{t('文字导出排除凭证与原音，不是完整备份或自动恢复包。真实异地云同步和后台链路仍待验收。','Text export excludes credentials and original audio; it is not a full backup or automatic restore package. Remote cloud sync and background operation still need validation.')}</p><a href="privacy.html" class="text-link">{c['privacycta']} →</a></div></section>'''
    details=f'''<section class="current-state"><div><p class="eyebrow">{t('边界清楚，才值得信任','CLEAR BOUNDARIES, BY DESIGN')}</p><h2>{t('现在能做什么，下一步做什么。','What works now. What comes next.')}</h2></div><details><summary>{t('来源与导入范围','Sources and import formats')}</summary><p>{t('UTF-8 文字文件支持 .md、.markdown、.txt、.text，单份不超过 2 MB；支持已适配 Codex、Claude Code 本地会话，以及导出聊天的 JSON / ZIP 导入。PDF、Office 文档与扫描件仍待适配。','UTF-8 text: .md, .markdown, .txt and .text, up to 2 MB each. Adapted Codex and Claude Code sessions and exported JSON / ZIP chat imports are supported. PDF, Office documents and scans still need support.')}</p></details><details><summary>{t('记录入口与真实设备','Capture entry points and real devices')}</summary><p>{t('手机、手表已有录音、暂停、保存与回放。快捷动作、操作按钮、轻点背面需要系统绑定，部分入口与手表操作仍待真机验收；不承诺任意后台触发。','Phone and watch recording, pause, save and playback exist. Shortcuts, Action Button and Back Tap require system configuration. Some entry points and watch interactions still need real-device validation; arbitrary background triggers are not promised.')}</p></details><details><summary>{t('模型、记忆与同步','Models, memory and sync')}</summary><p>{t('每日文字分析已有适配器、引用与失败保护，真实模型质量尚未验收。四类文字来源可手动提出候选，支持确认、修订、停用、恢复、依据和历史；自动模型记忆整理仍在开发。已有队列、校验、回执与资料夹交换，不等于真实云同步通过。自备模型服务可能收费，启用前请核对发送内容与服务商政策。','Daily text analysis has an adapter, citations and failure protection. Real-model quality is not yet validated. Four text source types support manual candidates, confirmation, revision, deactivation, restoration, evidence and history. Automated model memory organization remains in development. Queues, checksums, receipts and folder exchange do not mean real cloud sync is verified. Model providers may charge fees; check what is sent and their policies before activation.')}</p></details></section>'''
    end=f'''<section class="visual-end">{mark}<p class="eyebrow">OPEN SOURCE / MIT</p><h2>{t('一起，让记忆更有来处。','Give memory a source.<br>Build it with us.')}</h2><p>{t('从源码开始，从一个具体问题参与。','Start with the source. Contribute to a concrete problem.')}</p><div class="actions">{link('',c['source'],'button primary')}{link('/blob/main/ROADMAP.md',c['roadmap'],'text-link')}{link('/blob/main/CONTRIBUTING.md',c['contribute'],'text-link')}</div></section>'''
    return hero+capture+memory+source+files+details+end
